-- UEBRA ASISTENCIA V2 - SUPABASE
-- Ejecutar en SQL Editor de Supabase
create extension if not exists pgcrypto;

create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  nombre text not null, rol text not null check (rol in ('ADMIN','DOCENTE')), activo boolean default true
);
create table if not exists teachers (id uuid primary key default gen_random_uuid(), nombre text unique not null, profile_id uuid references profiles(id), activo boolean default true);
create table if not exists courses (id uuid primary key default gen_random_uuid(), clave text unique not null, nombre text not null, jornada text not null check (jornada in ('MATUTINA','VESPERTINA')), activo boolean default true);
create table if not exists students (id uuid primary key default gen_random_uuid(), cedula text, nombre text not null, sexo text, estado text not null default 'ACTIVO', course_id uuid references courses(id), fecha_ingreso date default current_date, fecha_salida date, updated_at timestamptz default now());
create unique index if not exists students_cedula_unique on students(cedula) where cedula is not null and cedula <> '';
create table if not exists schedules (id uuid primary key default gen_random_uuid(), teacher_id uuid references teachers(id), course_id uuid references courses(id), dia smallint not null check (dia between 1 and 5), periodo smallint not null, inicio time not null, fin time not null, asignatura text not null, activo boolean default true, unique(teacher_id,course_id,dia,periodo));
create table if not exists attendance_sessions (id uuid primary key default gen_random_uuid(), course_id uuid references courses(id), teacher_id uuid references teachers(id), fecha date not null, periodo smallint, asignatura text not null, created_by uuid references profiles(id), created_at timestamptz default now(), unique(course_id,fecha,periodo,asignatura));
create table if not exists attendance (id uuid primary key default gen_random_uuid(), session_id uuid references attendance_sessions(id) on delete cascade, student_id uuid references students(id), estado text not null check (estado in ('P','F','A','J')), observacion text default '', updated_at timestamptz default now(), unique(session_id,student_id));

-- Seguridad
alter table profiles enable row level security; alter table teachers enable row level security; alter table courses enable row level security; alter table students enable row level security; alter table schedules enable row level security; alter table attendance_sessions enable row level security; alter table attendance enable row level security;
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and rol='ADMIN' and activo); $$;

create policy "profiles_self" on profiles for select to authenticated using (id=auth.uid() or is_admin());
create policy "read_teachers" on teachers for select to authenticated using (true);
create policy "admin_teachers" on teachers for all to authenticated using (is_admin()) with check (is_admin());
create policy "read_courses" on courses for select to authenticated using (true);
create policy "admin_courses" on courses for all to authenticated using (is_admin()) with check (is_admin());
create policy "read_students" on students for select to authenticated using (true);
create policy "admin_students" on students for all to authenticated using (is_admin()) with check (is_admin());
create policy "read_schedules" on schedules for select to authenticated using (true);
create policy "admin_schedules" on schedules for all to authenticated using (is_admin()) with check (is_admin());
create policy "read_sessions" on attendance_sessions for select to authenticated using (true);
create policy "write_sessions" on attendance_sessions for insert to authenticated with check (created_by=auth.uid() or is_admin());
create policy "update_sessions" on attendance_sessions for update to authenticated using (created_by=auth.uid() or is_admin());
create policy "read_attendance" on attendance for select to authenticated using (true);
create policy "write_attendance" on attendance for insert to authenticated with check (exists(select 1 from attendance_sessions s where s.id=session_id and (s.created_by=auth.uid() or is_admin())));
create policy "update_attendance" on attendance for update to authenticated using (exists(select 1 from attendance_sessions s where s.id=session_id and (s.created_by=auth.uid() or is_admin())));

